referenceFixTemplate:
#include <stdio.h>

int main(void) {
    FILE *fp = fopen("dangan.txt", "w");
    if (fp == NULL) {
        return 0;
    }
    fprintf(fp, "小鱼干 {n} 条\n");
    fclose(fp);

    fp = fopen("dangan.txt", "r");
    char line[64];
    while (fgets(line, sizeof(line), fp) != NULL) {
        printf("读到：%s", line);
    }
    fclose(fp);
    return 0;
}
